Problem:
A sample can be analyzed by two machines for their chemical make-up, Analyzer 3000 and QuickAnalytics. Analyzer 3000 analyzes 20 samples of water and 30 samples of dirt per hour. QuickAnalytics examines 40 samples of water and 10 samples of dirt per hour. In addition, Analyzer 3000 creates 3.5 units of heat per hour while QuickAnalytics creates 4.5 units of heat per hour. If at least 1000 samples of water and 800 samples of dirt must be analyzed, how many hours should each machine be used to minimize the total amount of heat produced?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "hours of Analyzer 3000 used",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "hours of QuickAnalytics used",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "hours of Analyzer 3000 used",
     "coef": 3.5
    },
    {
     "var": "hours of QuickAnalytics used",
     "coef": 4.5
    }
   ]
  },
  "constraints": [
   {
    "name": "water samples analyzed",
    "terms": [
     {
      "var": "hours of Analyzer 3000 used",
      "coef": 20.0
     },
     {
      "var": "hours of QuickAnalytics used",
      "coef": 40.0
     }
    ],
    "sense": ">=",
    "rhs": 1000.0
   },
   {
    "name": "dirt samples analyzed",
    "terms": [
     {
      "var": "hours of Analyzer 3000 used",
      "coef": 30.0
     },
     {
      "var": "hours of QuickAnalytics used",
      "coef": 10.0
     }
    ],
    "sense": ">=",
    "rhs": 800.0
   }
  ]
 },
 "facts": {
  "objective": 140.0,
  "values": {
   "hours of Analyzer 3000 used": 22.0,
   "hours of QuickAnalytics used": 14.0
  },
  "binding": [
   "water samples analyzed",
   "dirt samples analyzed"
  ],
  "slack": {
   "water samples analyzed": 0.0,
   "dirt samples analyzed": 0.0
  },
  "shadow_prices": {
   "water samples analyzed": 0.1,
   "dirt samples analyzed": 0.05
  }
 }
}
